<script setup>import {ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';const result=ref(''),msg=ref('');const act=f=>{const r=f();msg.value=r.message||(r.ok?'操作成功':'操作失败')}</script>
<template><section class="h5-page"><div class="h5-module-hero"><span>演</span><h2>应急演练</h2><p>确认参与并提交执行结果</p></div><p v-if="msg" class="action-message">{{msg}}</p><article v-for="d in state.drills" :key="d.id" class="h5-card"><header><strong>{{d.name}}</strong><span>{{d.status}}</span></header><p>{{d.place}}</p><button v-if="d.status==='待启动'" class="primary-button active" @click="act(()=>actions.startDrill(d.id))">确认参与</button><template v-if="d.status==='执行中'"><input v-model="result" placeholder="填写执行结果"><button class="primary-button active" @click="act(()=>actions.submitDrill(d.id,result))">提交结果</button></template><p v-if="d.result">已提交：{{d.result}}</p></article></section></template>
